/**
 * Provider brand marks, vendored as raw SVG path data.
 *
 * These are third-party trademarks, used nominatively: they identify which vendor is answering a
 * prompt, which is the one thing a model picker exists to say. They are therefore kept as flat
 * compact glyphs, never as full-colour lockups, and they are never used to suggest endorsement.
 * By default a mark inherits `currentColor` (design language §7 — "a mark, not a logo moment"); a
 * mark MAY declare the one colour its vendor draws it in, for the few places where the provider's
 * identity is the point (the prompter's model chip, the picker's rows). Vendors with no single
 * brand colour for the glyph — OpenAI, Cursor — simply declare none: no colour is ever invented.
 *
 * Vendored rather than depended on because the set comes from several authoritative sources: the
 * ACP registry publishes the marks distributed with its agents, while Simple Icons and LobeHub fill
 * the few company marks the registry does not carry. Importing those packages would still not cover
 * the set, and their raw-SVG entry points do not work uniformly in tsc, Vitest, and Vite. Each entry
 * records its source so it can be re-derived or refreshed on demand.
 */
export type BrandMark = {
  /** One or more paths from the vendor asset. Multi-path marks stay multi-path rather than being redrawn. */
  d: string | readonly string[];
  /** Source coordinate system. Most marks are 24×24; official agent assets are not always. */
  viewBox?: string;
  /** The vendor's own colour for this glyph, when it has exactly one. Absent = always ink. */
  color?: string;
  /** Marks whose source declares `fill-rule="evenodd"`; nonzero would fill their negative space. */
  evenOdd?: true;
};

